"""One-time migration of the original standalone prototype into frontend source."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
source = (root / 'dist/index.html').read_text(encoding='utf-8')
source = source[:source.index('<script>')] + '<link rel="stylesheet" href="/static/refinements.css"><script src="/static/app.js" defer></script></html>'
source = source.replace('</style>', '''
.repository{border:1px solid #414b35;padding:20px;margin-bottom:24px}.repository form{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.repository input{color:#e3dfc8}.repository input[name=path]{flex:1;min-width:230px}.repository input[name=limit]{width:85px}.scope{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;color:#aab899}.warnings{color:#e3b18c;white-space:pre-wrap;line-height:1.7}.record{cursor:pointer}.record:hover{background:#d9dbc1}td{overflow-wrap:anywhere}td small{white-space:pre-wrap}button:focus-visible,input:focus-visible,tr:focus-visible{outline:2px solid #a64a38;outline-offset:3px}[hidden]{display:none!important}#verdict{width:min(680px,94vw);max-width:680px;max-height:90vh;overflow:auto}#judgment{padding:20px;border:3px double #8c9176}#judgment h2{text-align:center;font:30px SimSun,serif;letter-spacing:5px}#judgment dl{line-height:1.7}#judgment dt{color:#83896f;margin-top:12px}#judgment dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}#sentence{font:20px SimSun,serif;line-height:1.8;border-top:1px solid #92997a;padding-top:20px}.dialog-actions{display:flex;gap:12px;margin-top:20px}@media print{body>*:not(#verdict){display:none!important}#verdict{position:static;max-height:none;width:100%;max-width:none}.dialog-actions{display:none}}
</style>''')
source = source.replace('<header><span>仓库 / ancestral-code　⌄　 main</span><span>● 演示仓库 · 阴间已连接</span></header>', '<header><span id="repo-label">仓库 / 演示卷宗</span><span id="mode-label">● 演示模式 · 虚构数据</span></header>')
source = source.replace('<section class="stats">', '''<section class="repository"><form id="scan-form"><label for="repo-path">本地仓库</label><input id="repo-path" name="path" placeholder="E:\\项目\\我的仓库" required><label for="limit">提交上限</label><input id="limit" name="limit" type="number" value="200" min="1" max="1000" required><button class="btn" id="scan" type="submit">翻阅生死簿</button><button class="btn" id="demo" type="button">演示模式</button></form><p class="scope" id="scope">演示模式：以下人物、文件与剧情均为虚构。</p><p class="warnings" id="warnings" role="status" aria-live="polite"></p></section><section class="stats">''')
start = source.index('<section class="stats">'); end = source.index('<section class="book">', start)
source = source[:start] + '''<section class="stats"><div>删除记录<strong id="dead">0 次</strong><small>同一文件可多次入册</small></div><div>疑似还魂<strong id="alive">0 次</strong><small>删除后同路径重新出现</small></div><div>已检查提交<strong id="scanned">—</strong><small>HEAD 第一父提交链</small></div><div id="event-stat">演示异动<strong id="events">0 次</strong><small>仅为演示剧情</small></div></section>''' + source[end:]
source = source.replace('待轮回','未见重现').replace('已还魂','疑似还魂')
source = source.replace('<th>亡魂 / 生前居所</th><th>阳寿</th><th>超度人</th><th>死因</th><th>轮回</th>', '<th>文件 / 删除提交</th><th>存续时长</th><th>超度人 / 删除时间</th><th>提交信息</th><th>轮回 / 判决</th>')
source = source.replace('<script src=', '''<dialog id="verdict" aria-labelledby="judgment-title"><article id="judgment"><div class="eyebrow">冥府档案局 · 文件卷宗</div><h2 id="judgment-title">代码往生判决书</h2><p id="verdict-mode"></p><dl id="verdict-fields"></dl><p id="sentence"></p><p>判词为本地模板生成，仅供趣味展示。</p></article><div class="dialog-actions"><button class="btn" id="print">打印 / 保存 PDF</button><button class="btn" id="verdict-close">退堂</button></div></dialog><script src=''')
(root / 'frontend/index.html').write_text(source, encoding='utf-8')
